import { Injectable } from '@angular/core';
import { AuthenticationService } from '../services/authentication/authentication.service';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { environment } from '../../../environments/environment';
import { IUser } from '../models/user';
import { IDashboardResponse } from './i-dashboard';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class DashboardService {

  constructor(private _authenticationservice: AuthenticationService,
              private _httpclient: HttpClient) { }

  private baseUrl: string = environment.baseUrl;
  private currentuser: IUser;
  private httpOptions: {};

  private refreshCredentials() {
    this.currentuser = this._authenticationservice.currentUserValue;
    this.httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.currentuser.token}`
      })
    };
  }

  getData(): Observable<IDashboardResponse> {
    this.refreshCredentials();
    return this._httpclient.get<IDashboardResponse>(`${this.baseUrl}/dashboarddata` + (((this.currentuser.partnerinfo[0].cname === 'admin') || (this.currentuser.partnerinfo[0].cname === 'sales') || (this.currentuser.partnerinfo[0].cname === 'manager')) ? `` : `?partnerid=` + this.currentuser.partnerinfo[0].id), this.httpOptions);
  }

  getAllConfigurations():Observable<any>{
    let req_headers = new HttpHeaders();
    req_headers.append('Content-Type', 'application/json');
      return this._httpclient.get(`${this.baseUrl}/getconfig`, { headers: req_headers });
  }

}
